import React, { useState, useEffect, useRef } from 'react';
import { DATA, allTools } from '../data/toolsData';
import ToolCard from '../components/ToolCard';
import Modal from '../components/Modal';
import Footer from '../components/Footer';
import './Home.css';

const MARQUEE_ITEMS = allTools.slice(0, 16);
const FILTERS = [
  { label: 'All Tools', type: 'all' },
  { label: '✅ Free Only', type: 'free' },
  { label: '💎 Paid Only', type: 'paid' },
  { label: '🔓 Free+Paid', type: 'both' },
];

export default function Home() {
  const [searchQ, setSearchQ] = useState('');
  const [activeType, setActiveType] = useState('all');
  const [selectedTool, setSelectedTool] = useState(null);
  const [showScroll, setShowScroll] = useState(false);
  const searchRef = useRef(null);

  // Cursor
  useEffect(() => {
    const cursor = document.getElementById('cursor');
    const ring = document.getElementById('cursor-ring');
    const move = (e) => {
      if (cursor) { cursor.style.left = e.clientX + 'px'; cursor.style.top = e.clientY + 'px'; }
      if (ring) { ring.style.left = e.clientX + 'px'; ring.style.top = e.clientY + 'px'; }
    };
    document.addEventListener('mousemove', move);
    return () => document.removeEventListener('mousemove', move);
  }, []);

  useEffect(() => {
    const onScroll = () => setShowScroll(window.scrollY > 400);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Filter tools
  const filtered = DATA.map(cat => ({
    ...cat,
    tools: cat.tools
      .filter(t => activeType === 'all' || t.t === activeType)
      .filter(t => !searchQ || t.n.toLowerCase().includes(searchQ.toLowerCase()) || t.d.toLowerCase().includes(searchQ.toLowerCase()))
      .map(t => ({ ...t, icon: cat.icon, cat: cat.title })),
  })).filter(cat => cat.tools.length > 0);

  const surpriseMe = () => {
    const t = allTools[Math.floor(Math.random() * allTools.length)];
    setSelectedTool(t);
  };

  return (
    <>
      <div id="cursor" />
      <div id="cursor-ring" />
      <div className="orb orb1" />
      <div className="orb orb2" />
      <div className="orb orb3" />

      {/* HERO */}
      <section className="hero">
        <div className="hero-badge">
          <span className="live-dot" />
          <span>✨ 50+ AI Tools · Always Updated</span>
        </div>
        <h1 className="hero-h1">
          <span className="line1">Learn, Master &</span>
          <span className="grad-text"> Explore Every AI Tool</span>
        </h1>
        <p className="hero-sub">
          The ultimate free directory of AI tools with step-by-step guides, Hindi tutorials, and pro tips. No fluff — just everything you need.
        </p>
        <div className="search-wrap">
          <span className="search-icon">🔍</span>
          <input
            ref={searchRef}
            id="main-search"
            type="text"
            placeholder="Search ChatGPT, Midjourney, Sora…"
            value={searchQ}
            onChange={e => setSearchQ(e.target.value)}
          />
          {searchQ && (
            <button className="search-clear" onClick={() => setSearchQ('')}>✕</button>
          )}
        </div>
        <div className="hero-stats">
          <div className="stat">
            <span className="stat-num">{allTools.length}+</span>
            <span className="stat-label">AI Tools</span>
          </div>
          <div className="stat-sep" />
          <div className="stat">
            <span className="stat-num">13</span>
            <span className="stat-label">Categories</span>
          </div>
          <div className="stat-sep" />
          <div className="stat">
            <span className="stat-num">100%</span>
            <span className="stat-label">Free Access</span>
          </div>
          <div className="stat-sep" />
          <div className="stat">
            <span className="stat-num">Hindi</span>
            <span className="stat-label">Tutorials</span>
          </div>
        </div>
      </section>

      {/* MARQUEE */}
      <section className="marquee-section">
        <div className="marquee-inner">
          {[...MARQUEE_ITEMS, ...MARQUEE_ITEMS].map((t, i) => (
            <div className="marquee-item" key={i}>
              <span style={{ fontSize: 16 }}>{t.icon}</span>
              <span className="m-name">{t.n}</span>
              <span className={`badge badge-${t.t} m-type`}>{t.t}</span>
            </div>
          ))}
        </div>
      </section>

      {/* FILTER BAR */}
      <div className="filter-section" id="categories">
        <div className="filter-inner">
          {FILTERS.map(f => (
            <button
              key={f.type}
              className={`fbtn${activeType === f.type ? ' active' : ''}`}
              onClick={() => setActiveType(f.type)}
            >
              {f.label}
            </button>
          ))}
          <button className="fbtn surprise-btn" onClick={surpriseMe}>🎲 Surprise Me</button>
          {DATA.map(cat => (
            <button
              key={cat.title}
              className="fbtn"
              onClick={() => {
                const el = document.getElementById('cat-' + cat.title.replace(/\s/g, '-'));
                if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
              }}
            >
              {cat.icon} {cat.title.split(' ')[0]}
            </button>
          ))}
        </div>
      </div>

      {/* MAIN CONTENT */}
      <main className="main">
        {filtered.length === 0 ? (
          <div className="no-results">
            <h3>🔍 No tools found</h3>
            <p>Try a different search term or filter</p>
            <button className="btn-primary" style={{ maxWidth: 200, marginTop: 16 }} onClick={() => { setSearchQ(''); setActiveType('all'); }}>Clear Filters</button>
          </div>
        ) : (
          filtered.map(cat => (
            <section
              key={cat.title}
              className="section"
              id={'cat-' + cat.title.replace(/\s/g, '-')}
              style={{ '--cat-color': cat.color }}
            >
              <div className="sec-header">
                <div className="sec-icon-wrap" style={{ background: cat.color }}>
                  <span>{cat.icon}</span>
                </div>
                <div className="sec-title-group">
                  <span className="sec-title">{cat.title}</span>
                  <span className="sec-tool-logos">
                    {cat.tools.slice(0, 5).map(t => (
                      <img
                        key={t.n}
                        className="sec-tool-logo"
                        src={`https://www.google.com/s2/favicons?domain=${new URL(t.url).hostname}&sz=32`}
                        alt={t.n}
                        title={t.n}
                        onError={e => { e.target.style.display = 'none'; }}
                      />
                    ))}
                  </span>
                </div>
                <span className="sec-count">{cat.tools.length} tools</span>
              </div>
              <div className="grid">
                {cat.tools.map((tool) => (
                  <ToolCard key={tool.n} tool={tool} onOpenModal={setSelectedTool} />
                ))}
              </div>
            </section>
          ))
        )}
      </main>

      <Footer toolCount={allTools.length} />

      {/* SCROLL TOP */}
      {showScroll && (
        <button className="scroll-top" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>↑</button>
      )}

      {/* MODAL */}
      {selectedTool && <Modal tool={selectedTool} onClose={() => setSelectedTool(null)} />}
    </>
  );
}
